#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/postgres-16.16-alpine3.24-arm64-oci ] || "$F" docker.io/library/postgres sha256:40e58641410e030f5769096bca8372f68f243e1859c8ecdf11f227da390d514d postgres:16.16-alpine3.24 images/postgres-16.16-alpine3.24-arm64-oci
[ "$A" = arm64 ] || [ -f images/postgres-16.16-alpine3.24-amd64.docker.tar ] || "$F" docker.io/library/postgres sha256:a2f7e20374cd8fd8ed4a588b79549e10589bea7b1686e77922f5ac741b80b8a1 postgres:16.16-alpine3.24 images/postgres-16.16-alpine3.24-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/redis-7.4.7-alpine-arm64-oci ] || "$F" docker.io/library/redis sha256:eaa5baba4031beadea0a970d578807f96ff6caf9282f1878f316059ed889a178 redis:7.4.7-alpine images/redis-7.4.7-alpine-arm64-oci
[ "$A" = arm64 ] || [ -f images/redis-7.4.7-alpine-amd64.docker.tar ] || "$F" docker.io/library/redis sha256:b9f6cf0cab55fdd102fd2182deeae150457943d33439d18c6e2fc5666d3228c1 redis:7.4.7-alpine images/redis-7.4.7-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/ghcr.io-saleor-saleor-3.23.49-arm64-oci ] || "$F" ghcr.io/saleor/saleor sha256:1a9d2807214087dbd41bf78c44c951441f48c40f8afcc83f2d79f31e8efe79bd ghcr.io/saleor/saleor:3.23.49 images/ghcr.io-saleor-saleor-3.23.49-arm64-oci
[ "$A" = arm64 ] || [ -f images/ghcr.io-saleor-saleor-3.23.49-amd64.docker.tar ] || "$F" ghcr.io/saleor/saleor sha256:671845a6b5d92b93417095d5a8d1d88de85096a846b698499395c638ccfd1ff8 ghcr.io/saleor/saleor:3.23.49 images/ghcr.io-saleor-saleor-3.23.49-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/ghcr.io-saleor-saleor-3.23.49-amd64.docker.tar images/postgres-16.16-alpine3.24-amd64.docker.tar images/redis-7.4.7-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/ghcr.io-saleor-saleor-3.23.49-arm64-oci images/postgres-16.16-alpine3.24-arm64-oci images/redis-7.4.7-alpine-arm64-oci
